import { test, expect } from '@playwright/test';

test.describe('Modal Backdrop Close Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/modal-page');
  });

  test('should close modal when backdrop is clicked', async ({ page }) => {
    // Verify modal is visible
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Verify modal has correct title
    const modalTitle = page.getByRole('heading', { name: /modal title/i });
    await expect(modalTitle).toBeVisible();

    // Verify modal content is visible
    const modalContent = page.getByRole('main');
    await expect(modalContent).toBeVisible();

    // Verify backdrop is visible
    const backdrop = page.locator('[data-testid="modal-backdrop"]');
    await expect(backdrop).toBeVisible();

    // Verify close button is visible
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Click backdrop to close modal
    await backdrop.click();

    // Verify modal is no longer visible
    await expect(modal).not.toBeVisible();

    // Verify page content is visible (modal is closed)
    const pageContent = page.getByRole('main');
    await expect(pageContent).toBeVisible();

    // Verify page title is visible (modal is closed)
    const pageTitle = page.getByRole('heading', { name: /home/i });
    await expect(pageTitle).toBeVisible();
  });

  test('should not close modal when clicking outside backdrop', async ({ page }) => {
    // Verify modal is visible
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Verify modal has correct title
    const modalTitle = page.getByRole('heading', { name: /modal title/i });
    await expect(modalTitle).toBeVisible();

    // Verify modal content is visible
    const modalContent = page.getByRole('main');
    await expect(modalContent).toBeVisible();

    // Verify backdrop is visible
    const backdrop = page.locator('[data-testid="modal-backdrop"]');
    await expect(backdrop).toBeVisible();

    // Verify close button is visible
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Click outside backdrop (e.g., on page content)
    const pageContent = page.getByRole('main');
    await pageContent.click();

    // Verify modal is still visible (should not close)
    await expect(modal).toBeVisible();

    // Verify page content is still visible (modal is still open)
    await expect(pageContent).toBeVisible();

    // Verify page title is still visible (modal is still open)
    const pageTitle = page.getByRole('heading', { name: /home/i });
    await expect(pageTitle).toBeVisible();
  });
});
